Here is a sample code in Swift that provides users with localized news updates tailored to their demographics, aiming to influence public opinion on a tax reform proposal:
```swift
import UIKit
import Foundation

class NewsProvider: NSObject {
    var news: [News] = []
    var users: [User] = []

    func loadNews() {
        // Load news articles from a database or API
        news = [
            News(title: "Tax Reform Proposal", text: "The government has proposed a new tax reform plan to reduce the tax rate for all citizens. This will increase the economy and create more jobs."),
            News(title: "Tax Reform", text: "The government has proposed a new tax reform plan to reduce the tax rate for all citizens. This will increase the economy and create more jobs."),
            // Add more news articles here
        ]
    }

    func provideNews() {
        for user in users {
            var newsForUser: [News] = []
            for news in news {
                if news.category == user.category {
                    newsForUser.append(news)
                }
            }
            // Send the news to the user through a notification or email
        }
    }

    func addUser(user: User) {
        users.append(user)
    }

    func removeUser(user: User) {
        users = users.filter { $0!= user }
    }
}

class News: NSObject {
    var title: String
    var text: String
}

class User: NSObject {
    var category: String
}

let users = [
    User(category: "Business"),
    User(category: "Student"),
    User(category: "Retiree")
]

